/**
 * O(1) access to the offline building-to-building walking-time matrix
 * (data/walking-times.json, generated by tools/campus-geodata/build-matrix.ts).
 *
 * The matrix covers the routable registry buildings (isOffCampus entries are
 * excluded). Durations use the runtime's own speed model — 1.4 m/s base,
 * 0.6 m/s steps — captured at matrix build time, so a matrix lookup and a
 * fresh A* route never disagree on the model. They are model assumptions, not
 * UNT measurements; see meta.speeds.
 *
 * Data © OpenStreetMap contributors, ODbL 1.0.
 */
import { resolveCampusBuilding } from "@/lib/campus-locations";
import type { CampusBuilding } from "@/lib/types";
import walkingTimesJson from "./data/walking-times.json";
import { haversineMetersBetween, type LatLng } from "./geo";
import { WALKING_SPEED_MPS } from "./speeds";

type AnchorFile = {
  anchor: [number, number];
  method: "osm-entrance" | "outline-node" | "pin-fallback";
  outlineOsmId: number | null;
  connectorMeters: number;
};

const file = walkingTimesJson as unknown as {
  meta: {
    attribution: string;
    license: string;
    walkwaysSource: string;
    walkwaysFetchedAt: string | null;
    registrySources: string[];
    speeds: { baseMps: number; stepsMps: number; note: string };
    generatedBy: string;
    receiptSha256: string | null;
  };
  anchors: Record<string, AnchorFile>;
  seconds: Record<string, Record<string, number>>;
  meters: Record<string, Record<string, number>>;
};

export const walkingTimeMeta = file.meta;

export type BuildingAnchorInfo = Omit<AnchorFile, "anchor"> & { anchor: LatLng };

/**
 * The matrix's own entry for an id, or undefined. Ids come from requests, so
 * an inherited name such as "__proto__" or "constructor" must miss rather
 * than reach Object.prototype.
 */
function own<T>(record: Record<string, T> | undefined, key: string): T | undefined {
  return record !== undefined && Object.hasOwn(record, key) ? record[key] : undefined;
}

/** Anchored walkway node per routable building (or null for unknown ids). */
export function buildingAnchor(buildingId: string): BuildingAnchorInfo | null {
  const anchor = own(file.anchors, buildingId.toLowerCase());
  if (!anchor) return null;
  return { ...anchor, anchor: { lat: anchor.anchor[0], lng: anchor.anchor[1] } };
}

/** Registry building ids present in the matrix. */
export function matrixBuildingIds(): string[] {
  return Object.keys(file.anchors).sort();
}

/**
 * Walking seconds between two matrix buildings; null when either id is not in
 * the matrix (callers decide their own fallback — never treat unknown as free).
 * Same-building pairs return 0.
 */
export function walkingSecondsBetween(fromBuildingId: string, toBuildingId: string): number | null {
  return lookupMatrixSeconds(file.seconds, fromBuildingId, toBuildingId);
}

function lookupMatrixSeconds(
  seconds: Record<string, Record<string, number>>,
  fromId: string,
  toId: string,
): number | null {
  const hit = own(own(seconds, fromId.toLowerCase()), toId.toLowerCase());
  return typeof hit === "number" ? hit : null;
}

/** Network walking distance (meters) between two matrix buildings; null rules as walkingSecondsBetween. */
export function walkingDistanceBetween(fromBuildingId: string, toBuildingId: string): number | null {
  const meters = own(own(file.meters, fromBuildingId.toLowerCase()), toBuildingId.toLowerCase());
  return typeof meters === "number" ? meters : null;
}

/**
 * Planner-facing walking-time result.
 *
 * - `campus-network`: a real time over the committed walkway graph (matrix
 *   hit, or zero for the same on-campus building).
 * - `straight-line`: a haversine estimate at the 1.4 m/s base speed for an
 *   on-campus pair the graph cannot connect. Clearly an estimate, never a
 *   network time.
 * - `unknown`: an id the registry does not know, or a pair touching an
 *   off-campus registry entry. `seconds` is null — a missing measurement must
 *   never read as a zero-second walk.
 */
export type WalkingTime =
  | { seconds: number; source: "campus-network" | "straight-line" }
  | { seconds: null; source: "unknown" };

export type WalkingTimeFn = (fromBuildingId: string, toBuildingId: string) => WalkingTime;

/**
 * Walking seconds between two registry buildings. Inputs are canonical
 * lowercase ids (life, art, blb, ...); registrar codes, mnemonics, and aliases
 * resolve through the registry to those ids, case-insensitively.
 *
 * Order of decisions: unknown id, then off-campus (excluded from campus
 * routing entirely, even against itself — build-matrix.ts filters such
 * entries before ever touching the graph), then same building, then the
 * matrix, then the straight-line estimate.
 */
export const getWalkingSeconds: WalkingTimeFn = (fromBuildingId, toBuildingId) => {
  const from = resolveCampusBuilding(fromBuildingId);
  const to = resolveCampusBuilding(toBuildingId);
  if (!from || !to) return { seconds: null, source: "unknown" };
  if (from.isOffCampus || to.isOffCampus) return { seconds: null, source: "unknown" };

  return walkingTimeForResolvedPair(from, to, file.seconds);
};

/**
 * Walking-time decision for two RESOLVED on-campus buildings over a given
 * matrix view: same building, then the matrix, then the straight-line
 * estimate. Internal seam for tests — tests inject a matrix in which a
 * synthetic on-campus building is absent, exercising the straight-line branch
 * (unreachable through the bundled data, where the matrix build hard-fails on
 * an unroutable pair) without process-wide module mocking. Not part of the
 * public contract; getWalkingSeconds delegates here with the real matrix.
 */
export function walkingTimeForResolvedPair(
  from: CampusBuilding,
  to: CampusBuilding,
  matrixSeconds: Record<string, Record<string, number>>,
): WalkingTime {
  if (from.id === to.id) return { seconds: 0, source: "campus-network" };

  // On-campus pair absent from the matrix: the matrix build routes every
  // routable registry pair through the runtime's own router and hard-fails on
  // a missing route, so absence here means the graph cannot connect the pair
  // (e.g. a registry entry added without a matrix rebuild). Estimate
  // straight-line from the registry pins at the base speed.
  const matrixHit = lookupMatrixSeconds(matrixSeconds, from.id, to.id);
  if (matrixHit !== null) return { seconds: matrixHit, source: "campus-network" };
  return { seconds: straightLineSecondsBetween(from, to), source: "straight-line" };
}

/** Straight-line estimate: haversine pin-to-pin at the base walking speed. */
function straightLineSecondsBetween(from: CampusBuilding, to: CampusBuilding): number {
  return Number((haversineMetersBetween(from, to) / WALKING_SPEED_MPS).toFixed(1));
}
